            onPressed: () => context.push('/appointments/book'),
            icon: const Icon(Icons.calendar_month_outlined),
            label: const Text('Book appointment'),
          ),
          const SizedBox(height: 16),
        ],
        // 3. Find a Doctor Panel (Family Head only)
        if (widget.isHead) ...[
          Container(
            padding: const EdgeInsets.all(18),
            decoration: BoxDecoration(
              color: isDark ? const Color(0xFF1E293B) : Colors.white,
              borderRadius: BorderRadius.circular(18),
              border: Border.all(
                color: isDark
                    ? const Color(0xFF334155)
                    : const Color(0xFFE2E8F0),
              ),
              boxShadow: [
                BoxShadow(
                  color: Colors.black.withValues(alpha: isDark ? 0.3 : 0.03),
                  blurRadius: 12,
                  offset: const Offset(0, 4),
                ),
              ],
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'Find a doctor',
                  style: TextStyle(
                    fontSize: 17.5,
                    fontWeight: FontWeight.w700,
                    color: isDark ? Colors.white : const Color(0xFF0F172A),
                  ),
                ),
                const SizedBox(height: 14),

                // Search inputs
                TextField(
                  controller: _searchController,
                  decoration: const InputDecoration(
                    labelText: 'Search',
                    hintText: 'Name or specialty',
                    prefixIcon: Icon(Icons.search, size: 20),
                  ),
                  onSubmitted: (_) => _onSearch(),
                ),
                const SizedBox(height: 10),
                TextField(
                  controller: _districtController,
                  decoration: const InputDecoration(
                    labelText: 'District',
                    hintText: 'e.g. Colombo',
                    prefixIcon: Icon(Icons.location_on_outlined, size: 20),
                  ),
                  onSubmitted: (_) => _onSearch(),
                ),
                const SizedBox(height: 12),
                ElevatedButton(
                  onPressed: _onSearch,
                  style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFF1D61E0),
                    foregroundColor: Colors.white,
                    minimumSize: const Size(double.infinity, 44),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(10),
                    ),
                  ),
                  child: const Text(
                    'Search',
                    style: TextStyle(fontWeight: FontWeight.w700),
                  ),
                ),
                const SizedBox(height: 16),

                // Search results
                ref
                    .watch(doctorDirectoryProvider)
                    .when(
                      loading: () => const Padding(
                        padding: EdgeInsets.symmetric(vertical: 16),
                        child: Center(child: CircularProgressIndicator()),
                      ),
                      error: (_, _) => ErrorRetryView(
                        onRetry: () => ref.invalidate(doctorDirectoryProvider),
                      ),
                      data: (doctors) {
                        final districtFilter = ref
                            .watch(doctorDistrictFilterProvider)
                            .toLowerCase();
                        final filteredDoctors = districtFilter.isEmpty
                            ? doctors
                            : doctors
                                  .where(
                                    (d) => (d.district ?? '')
                                        .toLowerCase()
                                        .contains(districtFilter),
                                  )
                                  .toList();

                        if (filteredDoctors.isEmpty) {
                          return Container(
                            padding: const EdgeInsets.all(16),
                            alignment: Alignment.center,
                            child: Text(
                              'No verified doctors found. Try a different name, specialty or district.',
                              textAlign: TextAlign.center,
                              style: TextStyle(
                                fontSize: 13,
                                color: isDark
                                    ? AppColors.mutedDark
                                    : const Color(0xFF64748B),
                              ),
                            ),
                          );
                        }

                        return Column(
                          children: filteredDoctors
                              .map(
                                (doctor) => _DoctorDirectoryRow(
                                  doctor: doctor,
                                  onRequest: () => widget.onRequest(
                                    context,
                                    ref,
                                    widget.familyId,
                                    doctor.id,
                                    doctor.displayName,
                                  ),
                                ),
                              )
                              .toList(),
                        );
                      },
                    ),
              ],
            ),
          ),
        ],
      ],
    );
  }
}

