            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  children: [
                    Flexible(
                      child: Text(
                        doctor.displayName,
                        style: const TextStyle(
                          fontSize: 14.5,
